// Studio Downloads page. Reads studios/index.json, renders the archive, and builds a combined
// download from whatever is ticked.
//
// The manifest exists so this page never has to fetch every pack just to show counts and sizes.
// It is generated by tools/build-manifest.mjs, so those numbers always match the real files.

const listEl = document.getElementById('studioList')

if (listEl) {
  const searchEl = document.getElementById('studioSearch')
  const chipsEl = document.getElementById('cityChips')
  const countEl = document.getElementById('resultCount')
  const barEl = document.getElementById('selectionBar')
  const summaryEl = document.getElementById('selectionSummary')
  const downloadEl = document.getElementById('downloadCombined')
  const selectAllEl = document.getElementById('selectAll')
  const clearAllEl = document.getElementById('clearAll')

  let studios = []
  let city = 'All'
  // Selection is keyed by id rather than held on the checkboxes, so it survives a re-render when
  // the search or filter changes. Tick a studio, search for another, tick that too, download both.
  const selected = new Set()

  const formatSize = (bytes) => (bytes < 1024 * 1024 ? Math.round(bytes / 1024) + ' KB' : (bytes / 1024 / 1024).toFixed(1) + ' MB')

  const matches = (studio, query) => {
    if (city !== 'All' && studio.city !== city) return false
    if (!query) return true
    return (studio.name + ' ' + studio.city + ' ' + studio.note + ' ' + studio.gear).toLowerCase().includes(query)
  }

  function visible() {
    const query = searchEl.value.trim().toLowerCase()
    return studios.filter((s) => matches(s, query))
  }

  function renderChips() {
    const cities = ['All', ...[...new Set(studios.map((s) => s.city))].sort()]
    chipsEl.innerHTML = ''
    cities.forEach((name) => {
      const count = name === 'All' ? studios.length : studios.filter((s) => s.city === name).length
      const chip = document.createElement('button')
      chip.type = 'button'
      chip.className = 'chip' + (name === city ? ' is-active' : '')
      chip.setAttribute('aria-pressed', String(name === city))
      chip.textContent = name + ' ' + count
      chip.addEventListener('click', () => {
        city = name
        renderChips()
        renderList()
      })
      chipsEl.appendChild(chip)
    })
  }

  function studioRow(studio) {
    const row = document.createElement('div')
    row.className = 'studio-row'

    const box = document.createElement('input')
    box.type = 'checkbox'
    box.checked = selected.has(studio.id)
    box.setAttribute('aria-label', 'Select ' + studio.name)
    box.addEventListener('change', () => {
      if (box.checked) selected.add(studio.id)
      else selected.delete(studio.id)
      renderSelection()
    })

    const main = document.createElement('div')
    main.className = 'studio-main'

    const title = document.createElement('div')
    title.className = 'studio-name'
    title.textContent = studio.name
    const where = document.createElement('span')
    where.className = 'studio-city'
    where.textContent = studio.city
    title.appendChild(where)
    if (studio.roomLayout) title.appendChild(tag('Room layout', 'is-accent'))
    if (studio.builtIn) title.appendChild(tag('Ships with the app', ''))

    const meta = document.createElement('div')
    meta.className = 'studio-meta'
    const counts = [
      studio.counts.mics + ' mics',
      studio.counts.outboard + ' outboard',
      studio.counts.preamps + ' preamps'
    ].join(' · ')
    meta.textContent = counts + ' · ' + formatSize(studio.bytes) + ' · added ' + studio.added

    main.appendChild(title)
    main.appendChild(meta)

    const link = document.createElement('a')
    link.className = 'btn btn-small'
    link.href = studio.file
    link.setAttribute('download', '')
    link.textContent = 'Download'

    row.appendChild(box)
    row.appendChild(main)
    row.appendChild(link)
    return row
  }

  function tag(text, extra) {
    const el = document.createElement('span')
    el.className = 'tag ' + extra
    el.textContent = text
    return el
  }

  function renderList() {
    const shown = visible()
    listEl.innerHTML = ''

    if (shown.length === 0) {
      const empty = document.createElement('p')
      empty.className = 'archive-note'
      empty.textContent = 'No studios match that. Try a different city or search.'
      listEl.appendChild(empty)
      countEl.textContent = ''
      renderSelection()
      return
    }

    // City headings only make sense when nothing is filtering by city already; with a chip active
    // every row would sit under the same heading, which is just noise.
    if (city === 'All') {
      const byCity = new Map()
      shown.forEach((s) => {
        if (!byCity.has(s.city)) byCity.set(s.city, [])
        byCity.get(s.city).push(s)
      })
      ;[...byCity.keys()].sort().forEach((name) => {
        const heading = document.createElement('h2')
        heading.className = 'city-heading'
        heading.textContent = name
        listEl.appendChild(heading)
        byCity.get(name).forEach((s) => listEl.appendChild(studioRow(s)))
      })
    } else {
      shown.forEach((s) => listEl.appendChild(studioRow(s)))
    }

    countEl.textContent = shown.length === studios.length ? '' : shown.length + ' of ' + studios.length
    renderSelection()
  }

  function renderSelection() {
    const picked = studios.filter((s) => selected.has(s.id))
    if (picked.length === 0) {
      barEl.hidden = true
      return
    }
    const bytes = picked.reduce((n, s) => n + s.bytes, 0)
    const shownIds = new Set(visible().map((s) => s.id))
    const hidden = picked.filter((s) => !shownIds.has(s.id)).length
    const noun = picked.length === 1 ? 'studio' : 'studios'
    summaryEl.textContent =
      picked.length + ' ' + noun + ' selected, ' + formatSize(bytes) + (hidden ? ' (' + hidden + ' not shown by the current filter)' : '')
    barEl.hidden = false
  }

  // A studio export is { version, studios: [...] }, and the app's importer walks that array, so a
  // combined file is just every selected pack's studios concatenated under one version.
  async function downloadCombined() {
    const picked = studios.filter((s) => selected.has(s.id))
    if (picked.length === 0) return
    downloadEl.disabled = true
    downloadEl.textContent = 'Building…'
    try {
      const packs = await Promise.all(
        picked.map(async (s) => {
          const res = await fetch(s.file)
          if (!res.ok) throw new Error('Could not fetch ' + s.file)
          return res.json()
        })
      )
      // Every pack Julian publishes carries the same version, but take the highest rather than
      // silently mixing shapes if that ever stops being true.
      const version = Math.max(...packs.map((p) => p.version || 1))
      const merged = { version, studios: packs.flatMap((p) => p.studios) }
      const name = city === 'All' ? 'setup-sheet-helper-studios' : 'setup-sheet-helper-' + city.toLowerCase().replace(/[^a-z0-9]+/g, '-')
      const url = URL.createObjectURL(new Blob([JSON.stringify(merged, null, 2)], { type: 'application/json' }))
      const a = document.createElement('a')
      a.href = url
      a.download = name + '.json'
      document.body.appendChild(a)
      a.click()
      a.remove()
      URL.revokeObjectURL(url)
    } catch {
      summaryEl.textContent = 'Could not build that download. Try again, or grab the studios one at a time.'
    } finally {
      downloadEl.disabled = false
      downloadEl.textContent = 'Download combined'
    }
  }

  searchEl.addEventListener('input', renderList)
  downloadEl.addEventListener('click', downloadCombined)
  selectAllEl.addEventListener('click', () => {
    visible().forEach((s) => selected.add(s.id))
    renderList()
  })
  clearAllEl.addEventListener('click', () => {
    selected.clear()
    renderList()
  })

  async function load() {
    try {
      const res = await fetch('studios/index.json')
      if (!res.ok) throw new Error('manifest missing')
      studios = (await res.json()).studios
      renderChips()
      renderList()
    } catch {
      listEl.innerHTML = ''
      const err = document.createElement('p')
      err.className = 'archive-note'
      err.textContent = 'Could not load the studio list. Reload the page, or browse the studios folder on GitHub.'
      listEl.appendChild(err)
    }
  }

  load()
}
